237	index 0000000..e5919e0
238	--- /dev/null
239	+++ b/src/explore/stroll/camera.ts
240	@@ -0,0 +1,58 @@
241	+/* ============================ Đi dạo: camera sau lưng ============================
242	+   Camera quay quanh tâm xoay ở độ cao `cam.height` trên chân nhân vật, lùi `dist` theo yaw / pitch người chơi chọn (không tự quay theo nhân vật),
243	+   nhìn vào điểm `cam.look` trên chân. Tâm xoay trễ `lag` giây theo nhân vật cho chuyển động mềm.
244	+   Tránh vật cản bằng bản đồ 2D (spec §3 mục 4): đoạn mặt bằng từ TÂM NHÂN VẬT (vị trí thật, luôn hợp lệ) tới chỗ camera muốn đứng cắt bởi stSegClear
245	+   (tường cao vô hạn + mép vùng đi được), lùi thêm `gap`. Tường là cao vô hạn nên camera bị kéo lại gần thì nâng lên cho khoảng cách 3D tới tâm xoay
246	+   vẫn ≥ minDist (= max(minDist, dist × phần đi được) của plan, tính theo 3D): camera không bao giờ ra ngoài đoạn đã kiểm, nên không chui vào nhà.
247	+   Khoảng mặt bằng cho phép co lại ngay, nở ra theo `lag` (không giật khi vừa thoát góc tường).
248	+   Cuối cùng kẹp độ cao: ≥ cao độ đứng tại chỗ camera + 0,3 m, ngoài vùng thì ≥ landY. Không cấp phát (D-018). */
249	+import * as THREE from 'three';
250	+import { CONFIG } from '../../config';
251	+import { stSegClear, stGroundY, type StMap } from './map';
252	+
253	+export interface StCam { yaw: number; pitch: number }
254	+
255	+const ST_CAM_FLOOR = 0.3;   // m — camera cao hơn cao độ đứng tại chỗ nó ít nhất chừng này (plan Task 6)
256	+const piv = { x: 0, y: 0, z: 0, ok: false };   // tâm xoay đã trễ
257	+let reach = Infinity;                           // khoảng mặt bằng camera đang được phép lùi, m
258	+
259	+export function stCamPlace(camera: THREE.PerspectiveCamera, target: THREE.Vector3, s: { x: number; y: number; z: number }, c: StCam, map: StMap, dt: number, snap?: boolean): void {
260	+  const K = CONFIG.stroll.cam;
261	+  /* 1) tâm xoay trễ theo nhân vật */
262	+  const hy = s.y + K.height;
263	+  if (snap || !piv.ok) { piv.x = s.x; piv.y = hy; piv.z = s.z; piv.ok = true; }
264	+  else if (dt > 0) { const k = 1 - Math.exp(-dt / K.lag); piv.x += (s.x - piv.x) * k; piv.y += (hy - piv.y) * k; piv.z += (s.z - piv.z) * k; }
265	+  /* 2) chỗ camera muốn đứng: lùi dist theo yaw / pitch */
266	+  const cp = Math.cos(c.pitch), sp = Math.sin(c.pitch), fx = Math.cos(c.yaw), fz = -Math.sin(c.yaw);
267	+  const bx = piv.x - fx * K.dist * cp, bz = piv.z - fz * K.dist * cp;
268	+  let cy = piv.y + K.dist * sp;
269	+  /* 3) cắt theo bản đồ từ tâm nhân vật */
270	+  let dx = bx - s.x, dz = bz - s.z;
271	+  const L = Math.sqrt(dx * dx + dz * dz);
272	+  if (L > 1e-6) { dx /= L; dz /= L; } else { dx = -fx; dz = -fz; }
273	+  const t = L > 1e-6 ? stSegClear(map, s.x, s.z, bx, bz) : 1;
274	+  let allow = t >= 1 ? L : L * t - K.gap;
275	+  if (allow < 0) allow = 0;
276	+  if (snap || allow < reach || !(dt > 0)) reach = allow;
277	+  else reach += (allow - reach) * (1 - Math.exp(-dt / K.lag));
278	+  const h = reach < L ? reach : L;
279	+  const cx = s.x + dx * h, cz = s.z + dz * h;
280	+  /* 4) khoảng cách 3D tới tâm xoay thật ≥ minDist: thiếu thì nâng camera (không lùi thêm vào tường) */
281	+  const up = cy - hy;
282	+  if (h * h + up * up < K.minDist * K.minDist) { const need = Math.sqrt(K.minDist * K.minDist - h * h); if (up < need) cy = hy + need; }
283	+  /* 5) không thấp hơn mặt đứng tại chỗ camera / mặt đất */
284	+  const g = stGroundY(map, cx, cz);
285	+  const floor = g === g ? g + ST_CAM_FLOOR : CONFIG.landY;
286	+  if (cy < floor) cy = floor;
287	+  camera.position.set(cx, cy, cz);
288	+  target.set(piv.x, piv.y - K.height + K.look, piv.z);
289	+  camera.lookAt(target);
290	+}
291	+
292	+/* Kéo chuột / vuốt: sang phải quay camera sang phải (yaw giảm), kéo xuống nâng camera nhìn xuống (pitch tăng) */
293	+export function stCamDrag(c: StCam, dxPx: number, dyPx: number, sens: number): void {
294	+  const K = CONFIG.stroll.cam;
295	+  c.yaw -= dxPx * sens;
296	+  c.pitch += dyPx * sens;
297	+  if (c.pitch < K.pitchMin) c.pitch = K.pitchMin; else if (c.pitch > K.pitchMax) c.pitch = K.pitchMax;
298	+}
