421	+/* ============================ Đi dạo: đầu vào từ bàn phím (thuần) ============================
422	+   W/↑ tới, S/↓ lùi, A/← trái, D/→ phải theo hướng camera; chéo chuẩn hóa về độ dài 1; Shift chạy; Space nhảy.
423	+   Nhảy ở đây chỉ phản ánh phím đang giữ: index.ts biến nó thành một lần nhảy mỗi lần bấm (stStep nhảy mỗi khung jump = true khi chạm đất).
424	+   Không cấp phát (gọi mỗi khung). */
425	+import type { StInput } from './motion';
426	+
427	+export function stInputFromKeys(keys: Set<string>, camYaw: number, out: StInput): StInput {
428	+  let f = 0, r = 0;
429	+  if (keys.has('w') || keys.has('arrowup')) f += 1;
430	+  if (keys.has('s') || keys.has('arrowdown')) f -= 1;
431	+  if (keys.has('d') || keys.has('arrowright')) r += 1;
432	+  if (keys.has('a') || keys.has('arrowleft')) r -= 1;
433	+  const len = Math.sqrt(f * f + r * r);
434	+  if (len > 1) { f /= len; r /= len; }
435	+  out.mz = f; out.mx = r; out.run = keys.has('shift'); out.jump = keys.has(' '); out.camYaw = camYaw;
436	+  return out;
437	+}
